python3 << 'EOF'
import csv

cities = ["Minneapolis", "Akron", "Cincinnati", "Cleveland", "Columbus", "Dayton", "Toledo"]

dist = {}
with open("data/googleDistanceMatrix/distance.csv", "r", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for row in reader:
        o = row["origin"].strip()
        d = row["destination"].strip()
        if o in cities and d in cities:
            dist[(o, d)] = (row["cost"], row["duration"], row["distance"])

# Print all pairs
print("Distances between cities:")
for o in cities:
    for d in cities:
        if o != d and (o, d) in dist:
            print(f"  {o} -> {d}: cost={dist[(o,d)][0]}, duration={dist[(o,d)][1]}, distance={dist[(o,d)][2]}")
EOF

