import csv

cities = ["Cleveland", "Akron", "Toledo", "Minneapolis"]
pet_friendly = {c: [] for c in cities}

with open("data/accommodations/clean_accommodations_2022.csv", "r", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for row in reader:
        city = row.get("city", "").strip()
        rules = row.get("house_rules", "")
        if "No pets" in rules:
            continue
        if city in pet_friendly:
            pet_friendly[city].append({
                "name": row.get("NAME", ""),
                "price": float(row.get("price", 0)) if row.get("price") else 0,
                "room": row.get("room type", ""),
                "max_occ": row.get("maximum occupancy", ""),
                "rules": rules
            })

for c, items in pet_friendly.items():
    print(f"\n=== {c} ({len(items)} pet-friendly) ===")
    for it in items:
        print(f"  {it['name'][:55]:55} | ${it['price']:.0f} | {it['room'][:15]:15} | max_occ={it['max_occ']} | rules={it['rules']}")
EOF

